const money = cents => (cents/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const $ = s => document.querySelector(s);
let group='Todos', query='', cart=JSON.parse(sessionStorage.getItem('almeida-cart')||'[]');
const groups=['Todos',...new Set(produtos.map(p=>p.grupo))];
function render(){
 $('#filters').innerHTML=groups.map(g=>`<button class="${g===group?'active':''}" data-group="${g}">${g}</button>`).join('');
 const list=produtos.filter(p=>(group==='Todos'||p.grupo===group)&&`${p.nome} ${p.marca}`.toLocaleLowerCase('pt-BR').includes(query));
 $('#result-count').textContent=`${list.length} produtos`;$('#grid').innerHTML=list.map(p=>`<article class="card" data-id="${p.id}"><a class="card-open" href="produto.html?id=${encodeURIComponent(p.id)}">${p.imagem?`<img class="card-image processing" data-clean-image src="${p.imagem}" alt="${p.nome}">`:`<div class="photo">${p.marca[0]}</div>`}<div class="card-content"><small>${p.marca.toUpperCase()} · ${p.grupo}</small><h3>${p.nome}</h3><div class="variant">${p.variacoes.length>1?`${p.variacoes.length} variações`:(p.variacoes[0].nome==='Padrão'?'':p.variacoes[0].nome)}</div><div class="card-price">${cardPrice(p,0)}</div></div></a><div class="quick-buy"><label>Variação<select data-variant>${p.variacoes.map((v,index)=>`<option value="${index}">${v.nome}</option>`).join('')}</select></label><label>Qtd.<input data-quantity type="number" min="1" value="1" inputmode="numeric"></label><button data-add class="quick-add">Adicionar</button></div></article>`).join('');
 $('#cart-count').textContent=cart.reduce((n,i)=>n+i.qty,0);
 AlmeidaImageCleanup.watch($('#grid'));
}
function cardPrice(p,variantIndex){const v=p.variacoes[variantIndex];return `<strong>${money(v.preco)}</strong><div class="cash">${money(Math.round(v.preco*.9))} no PIX/dinheiro</div><div class="installments">ou até 4x sem juros no cartão</div>`}
function saveCart(){sessionStorage.setItem('almeida-cart',JSON.stringify(cart))}
function openProduct(id){const p=produtos[id];$('#product-detail').innerHTML=`<div class="photo detail-hero">${p.marca[0]}</div><small class="detail-meta">${p.marca.toUpperCase()} · ${p.grupo}</small><h2>${p.nome}</h2><p class="detail-description">Produto da linha ${p.marca}. Selecione a variação desejada. Especificações técnicas e fotos individuais serão adicionadas após validação com o fabricante.</p><label class="field">Variação<select id="variant">${p.variacoes.map((v,i)=>`<option value="${i}">${v.nome} · ${money(v.preco)}</option>`).join('')}</select></label><p id="detail-price"></p><button class="primary" id="add">Adicionar ao carrinho</button>`;const update=()=>{let v=p.variacoes[Number($('#variant').value)];$('#detail-price').innerHTML=`<strong>${money(v.preco)}</strong><br><span style="color:#ffd026">${money(Math.round(v.preco*.9))} no PIX/dinheiro</span>`};$('#variant').onchange=update;update();$('#add').onclick=()=>{let vi=Number($('#variant').value),item=cart.find(i=>i.id===id&&i.vi===vi);if(item)item.qty++;else cart.push({id,vi,qty:1});render();$('#product-dialog').close();openCart()};$('#product-dialog').showModal()}
function openCart(){let subtotal=cart.reduce((n,i)=>n+produtos[i.id].variacoes[i.vi].preco*i.qty,0);$('#cart-items').innerHTML=cart.map((i,k)=>{let p=produtos[i.id],v=p.variacoes[i.vi];return `<div class="row"><div><strong>${p.nome}</strong><br><small>${v.nome} · ${i.qty} × ${money(v.preco)}</small></div><button class="secondary" data-remove="${k}" aria-label="Remover">×</button></div>`}).join('');$('#checkout').innerHTML=cart.length?`<div class="totals">Produtos: <strong>${money(subtotal)}</strong><br>PIX/dinheiro (10% OFF): <strong>${money(Math.round(subtotal*.9))}</strong><br>Cartão: até 4x sem juros</div><label class="field">Pagamento<select id="payment"><option value="pix">PIX</option><option value="dinheiro">Dinheiro</option><option value="cartao">Cartão</option></select></label><label class="field">Recebimento<select id="fulfillment"><option value="retirada">Retirada na loja</option><option value="entrega">Entrega</option></select></label><div id="address-fields"></div><p class="notice">Pedido enviado pelo WhatsApp para confirmação. Nesta prévia, não há login, reserva de cashback ou pedido registrado no banco.</p><button class="primary" id="send">Enviar pedido pelo WhatsApp</button>`:'';$('#fulfillment')?.addEventListener('change',address);address();$('#send')?.addEventListener('click',send);$('#cart-dialog').showModal()}
function address(){let delivery=$('#fulfillment')?.value==='entrega';$('#address-fields').innerHTML=delivery?'<label class="field">Endereço de entrega<textarea id="address" rows="3" placeholder="Rua, número, bairro, cidade e referência"></textarea></label>':''}
function send(){let payment=$('#payment').value,delivery=$('#fulfillment').value==='entrega',addr=$('#address')?.value.trim();if(delivery&&!addr){$('#address').focus();return}let subtotal=cart.reduce((n,i)=>n+produtos[i.id].variacoes[i.vi].preco*i.qty,0),final=payment==='cartao'?subtotal:Math.round(subtotal*.9),lines=cart.map(i=>{let p=produtos[i.id],v=p.variacoes[i.vi];return `${i.qty}× ${p.nome} — ${v.nome} — ${money(v.preco*i.qty)}`});let msg=`Olá! Gostaria de fazer um pedido na Almeida Construções.\n\n${lines.join('\n')}\n\nProdutos: ${money(subtotal)}\nPagamento: ${payment==='pix'?'PIX':payment==='dinheiro'?'Dinheiro':'Cartão (até 4x sem juros)'}\n${payment==='cartao'?'':'Desconto à vista (10%): −'+money(subtotal-final)+'\n'}Total: ${money(final)}\nRecebimento: ${delivery?'Entrega':'Retirada na loja'}${delivery?'\nEndereço: '+addr:''}\n\nPedido sujeito à confirmação de disponibilidade dos produtos em estoque. ${delivery?'Frete a confirmar pela loja.':''}`;window.open('https://wa.me/553220201300?text='+encodeURIComponent(msg),'_blank','noopener')}
$('#filters').onclick=e=>{if(e.target.dataset.group){group=e.target.dataset.group;render()}};$('#grid').onchange=e=>{if(!e.target.matches('[data-variant]'))return;const card=e.target.closest('[data-id]'),p=produtos[Number(card.dataset.id)];card.querySelector('.card-price').innerHTML=cardPrice(p,Number(e.target.value))};$('#grid').onclick=e=>{const add=e.target.closest('[data-add]');if(!add)return;const card=add.closest('[data-id]'),id=Number(card.dataset.id),vi=Number(card.querySelector('[data-variant]').value),qty=Math.max(1,Math.floor(Number(card.querySelector('[data-quantity]').value)||1)),item=cart.find(i=>i.id===id&&i.vi===vi);if(item)item.qty+=qty;else cart.push({id,vi,qty});saveCart();render()};$('#search').oninput=e=>{query=e.target.value.toLocaleLowerCase('pt-BR');render()};$('#cart-button').onclick=openCart;$('#cart-items').onclick=e=>{if(e.target.dataset.remove!==undefined){cart.splice(Number(e.target.dataset.remove),1);saveCart();$('#cart-dialog').close();render();openCart()}};document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>b.closest('dialog').close());function info(title){$('#info').innerHTML=`<h2>${title}</h2><p>Cadastro, pedidos e cashback precisam do backend Supabase. Esta versão permite consultar o catálogo e montar o pedido para WhatsApp, mas ainda não registra uma compra na conta.</p>`;$('#info-dialog').showModal()}$('#account').onclick=()=>info('Minha conta');$('#orders').onclick=()=>info('Meus pedidos');render();
async function loadCatalogFromSupabase(){
  try{
    const response=await fetch(ALMEIDA_SUPABASE_URL+'/rest/v1/products?active=eq.true&select=brand,name,subcategory,image_url,image_override_url,product_variants(name,price_cents,active)&order=name.asc',{headers:{apikey:ALMEIDA_SUPABASE_KEY,Authorization:'Bearer '+ALMEIDA_SUPABASE_KEY}});
    if(!response.ok) throw new Error('Catalog status '+response.status);
    const remote=await response.json();
    const normalized=remote.map((p,id)=>({id,marca:p.brand,nome:p.name,grupo:p.subcategory,imagem:p.image_override_url||localProductImage(p.brand,p.name,p.image_url),variacoes:(p.product_variants||[]).filter(v=>v.active).map(v=>({nome:v.name,preco:v.price_cents}))})).filter(p=>p.variacoes.length);
    if(normalized.length){produtos=normalized;render()}
  }catch(error){console.info('Catálogo local usado enquanto o banco não está disponível.',error)}
}
loadCatalogFromSupabase();
if('serviceWorker'in navigator)navigator.serviceWorker.register('sw.js');
